create table if not exists public.match_likes (user_id uuid not null references auth.users(id) on delete cascade, candidate_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,candidate_id), constraint match_like_not_self check(user_id<>candidate_id));
create table if not exists public.match_skips (user_id uuid not null references auth.users(id) on delete cascade, candidate_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,candidate_id), constraint match_skip_not_self check(user_id<>candidate_id));
create table if not exists public.matches (id uuid primary key default gen_random_uuid(), user_a uuid not null references auth.users(id) on delete cascade, user_b uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), unique(user_a,user_b), constraint match_users_ordered check(user_a<user_b));
alter table public.match_likes enable row level security; alter table public.match_likes force row level security;
alter table public.match_skips enable row level security; alter table public.match_skips force row level security;
alter table public.matches enable row level security; alter table public.matches force row level security;
create policy "Members manage own match likes" on public.match_likes for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Members manage own match skips" on public.match_skips for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Members read own matches" on public.matches for select to authenticated using(auth.uid()=user_a or auth.uid()=user_b);
create or replace function public.record_match_like(p_candidate_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare a uuid; b uuid; matched boolean; begin if auth.uid() is null or p_candidate_id=auth.uid() then raise exception 'invalid_candidate'; end if; insert into public.match_likes(user_id,candidate_id) values(auth.uid(),p_candidate_id) on conflict do nothing; a:=least(auth.uid(),p_candidate_id); b:=greatest(auth.uid(),p_candidate_id); matched:=exists(select 1 from public.match_likes where user_id=p_candidate_id and candidate_id=auth.uid()); if matched then insert into public.matches(user_a,user_b) values(a,b) on conflict do nothing; end if; return matched; end; $$;
create or replace function public.record_match_skip(p_candidate_id uuid) returns boolean language plpgsql security invoker set search_path=public as $$ begin insert into public.match_skips(user_id,candidate_id) values(auth.uid(),p_candidate_id) on conflict do nothing; return true; end; $$;
create or replace function public.get_my_matches() returns table(match_id uuid, other_user_id uuid, display_name text, handle text, created_at timestamptz) language sql security definer set search_path=public as $$ select m.id, case when m.user_a=auth.uid() then m.user_b else m.user_a end, p.display_name,p.handle,m.created_at from public.matches m join public.profiles p on p.user_id=case when m.user_a=auth.uid() then m.user_b else m.user_a end where auth.uid()=m.user_a or auth.uid()=m.user_b order by m.created_at desc; $$;
revoke execute on function public.record_match_like(uuid),public.record_match_skip(uuid),public.get_my_matches() from public,anon;
grant execute on function public.record_match_like(uuid),public.record_match_skip(uuid),public.get_my_matches() to authenticated;
